from collections import Counter
def transform(g):
    F=Counter(c for r in g for c in r if c).most_common(1)[0][0]  # frame color
    W=len(g[0])
    # left box: columns until first all-zero column
    w=0
    while w<W and any(r[w] for r in g): w+=1
    box=[r[:w] for r in g]
    H=len(box)
    # border rows: rows fully frame color in box
    border=[i for i,r in enumerate(box) if all(c==F for c in r)]
    # right shapes: components per color
    shapes={}
    for i,r in enumerate(g):
        for j,c in enumerate(r):
            if c and j>=w:
                shapes.setdefault(c,[]).append((i,j))
    norm={}
    for c,cells in shapes.items():
        rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
        norm[c]=frozenset((p[0]-min(rs),p[1]-min(cs)) for p in cells)
    out=[r[:] for r in box]
    for a,b in zip(border,border[1:]):
        h=b-a-1
        interior=[(i,j) for i in range(a+1,b) for j in range(1,w-1)]
        z={(i-a-1,j-1) for i,j in interior if box[i][j]==0}
        if not z: continue
        # best-overlap shape
        best=max(norm, key=lambda c: len(norm[c]&z))
        for i,j in interior:
            if box[i][j]==0: out[i][j]=best
    return out

